import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"64、【未濟】 坎下離上","description":"周易口訣義 - 64、【未濟】 坎下離上","frontmatter":{"title":"64、【未濟】 坎下離上","description":"周易口訣義 - 64、【未濟】 坎下離上"},"headers":[],"relativePath":"classics/koujueyi/066.md","filePath":"classics/koujueyi/066.md"}'),r={name:"classics/koujueyi/066.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_64、【未濟】-坎下離上" tabindex="-1">64、【未濟】 坎下離上 <a class="header-anchor" href="#_64、【未濟】-坎下離上" aria-label="Permalink to “64、【未濟】 坎下離上”">​</a></h1><p>彖曰：「未濟亨」，柔得中也。「小狐汔濟」，未出中也。「濡其尾，無攸利」，不續終也。雖不當位，剛柔應也。</p><p>象曰：火在水上，未濟。君子以慎辨物居方。</p><p>初六：濡其尾，吝。</p><p>象曰：「濡其尾」，亦不知極也。</p><p>九二：曳其輪，貞吉。</p><p>象曰：九二貞吉，中以行正也。</p><p>六三：未濟，徵兇，利涉大川。</p><p>象曰：「未濟徵兇」，位不當也。</p><p>九四：貞吉悔亡。震用伐鬼方，三年有賞於大國。</p><p>象曰：「貞吉悔亡」，志行也。</p><p>六五，貞吉無悔，君子之光，有孚吉。</p><p>象曰：「君子之光」，其暉吉也。</p><p>上九，有孚於飲酒，無咎。濡其首，有孚失是。</p><p>象曰：飲酒濡首，亦不知節也。</p><p>解讀</p><p>「未濟，亨」者，未濟是未能濟渡之名，喻人德薄居位，才德劣小，不能拔濟危難，必須任之於賢，委之於德，則有可濟之理，故曰</p><p>「未濟亨」也。「小狐汔濟，濡其尾，無攸利」者，汔，將盡之名，其猶小才之人，不能濟拔險難，譬之小狐渡水，智力羸劣，必須待水乾淺方可涉川，未及於岸，力已疲憊，遂濡溼其尾，幾至沒溺，豈有利焉？故曰「濡其尾，無攸利」也。</p><p>象曰「火在水上，未濟」者，夫水火之用，相合而成，即能濟人之性命。今火居其上而上炎，水流於下而下注，火水各抗，焉能烹飪？故為未濟也。「君子以慎辨物居方」者，君子見未濟之患，以謹慎為用，故分辨事物，各安其居也。</p><p>「初六，濡其尾，吝」者，初六處未濟之初，最居險下，而欲強進求濟，其如力薄何？所以進未達岸，濡溼其尾，故曰「濡其尾」也。然體雖陰柔，不為剛狠之性，而乃猶不思反，以斯而往，頑亦甚矣，故曰「吝」也。</p><p>「九二，曳其輪，貞吉」者，九二以剛居中，而應於五，為君委任，即是救難之人。然二雖處險中，不為難之所溺，故經綸屯蹇，任重憂深，所以曳拔其輪，以出險外，故曰「曳其輪」也。救難濟危，莫過於正，故曰「貞吉」也。</p><p>「六三，未濟，徵兇，利涉大川」者，六三處未濟之時，以陰柔之質，失位之正，安能自濟？若徵而求濟，必致兇危，故曰「未濟，徵兇」也。然九二剛陽，為君委任，即是能救難之人；六三若能委質親二，即不慮沒溺，自然獲濟，故曰「利涉大川」也。</p><p>「九四，貞吉，悔亡，震用伐鬼方，三年有賞於大國」者，九四履失其位，所以有悔。然出險難之外，居文明之初，接近於君，志行其正，所以獲吉，憂悔乃亡，故曰「貞吉，悔亡」也。為君所任，正志既行，靡有禁其威者，故震發威怒，以伐遠方，故曰「震用伐鬼方」。鬼方者，興衰之徵也，每至興衰取義焉。四方文明之初，其德未盛，不能即服，故曰「三年」也。五處中位，體包明德，既居尊位，不奪物功，九四既有功勞，而乃以百里之國賞之，謂封以茅土，故曰「有賞於大國」也。</p><p>「六五，貞吉，無悔。君子之光，有孚，吉」者，以柔居尊，所以有悔。然以文明之質，為未濟之主，故必貞正，所以獲吉，憂悔乃亡，故曰「貞吉，無悔」也。以文明之質，居於尊位，不自任察，而委於二，是使武以文，御剛以柔，故有君子之光輝也。委其權於有能之人，而心不疑，則人皆竭其誠信，功勞克濟，故曰「有孚吉」也。</p><p>上九，有孚於飲酒，無咎。「濡其首，有孚失是」者，處未濟之極，即入於既濟，既得濟矣，任人又當，心即無疑，信任得人，自取逸樂，飲酒而已，不慮危咎，故曰「有孚於飲酒，無咎」也。飲酒不節，樂過淫荒，所以濡首之難，還復及之，故曰「濡其首」也。所以濡首之難及之者，良由信任於人，不憂禍患，失於所是，故曰「有孚失是」。</p>',25)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
